Here is a simple expense tracker for Oct 2026. Add an item, pick a category, and the totals update as you go. Entries stay on this page only while it is open, so note down anything you want to keep.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f7f7f5;color:#222}
h2{margin:0 0 12px;font-size:18px}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:100px}
button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
button.x{background:none;color:#b00;padding:2px 8px}
.card{background:#fff;border-radius:8px;padding:12px;margin-bottom:12px}
.total{font-size:22px;font-weight:600}
.bar{height:8px;background:#2f7d5b;border-radius:4px}
.cat{margin:6px 0;font-size:13px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
.muted{color:#777;font-size:12px}
</style>
</head>
<body>
<h2>Expenses for October 2026</h2>
<div class="row">
<input id="name" placeholder="What did you spend on?">
<input id="amt" type="number" min="0" placeholder="Amount (₹)">
<select id="cat">
<option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Fun</option><option>Other</option>
</select>
<button id="add" type="button">Add</button>
</div>
<div class="card">
<div class="muted">Total this month</div>
<div class="total" id="total">₹0</div>
<div class="row" style="margin:8px 0 0">
<input id="budget" type="number" min="0" placeholder="Monthly budget (₹), optional">
</div>
<div class="muted" id="left"></div>
</div>
<div class="card"><div class="muted">By category</div><div id="cats"></div></div>
<div class="card"><div class="muted">All entries</div><div id="list"></div></div>
<script>
var items=[];
var fmt=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
function render(){
var t=0,by={};
items.forEach(function(i){t+=i.a;by[i.c]=(by[i.c]||0)+i.a});
document.getElementById("total").textContent=fmt(t);
var b=parseFloat(document.getElementById("budget").value);
var l=document.getElementById("left");
if(b>0){l.textContent=t<=b?fmt(b-t)+" left of your budget":fmt(t-b)+" over your budget"}else{l.textContent=""}
var cats=document.getElementById("cats");cats.innerHTML="";
Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
var d=document.createElement("div");d.className="cat";
var s=document.createElement("div");s.textContent=k+": "+fmt(by[k]);
var bar=document.createElement("div");bar.className="bar";bar.style.width=(by[k]/t*100)+"%";
d.appendChild(s);d.appendChild(bar);cats.appendChild(d)});
var list=document.getElementById("list");list.innerHTML="";
if(!items.length){list.innerHTML='<div class="muted">Nothing yet.</div>'}
items.forEach(function(i,idx){
var r=document.createElement("div");r.className="item";
var s=document.createElement("span");s.textContent=i.n+" ("+i.c+") · "+fmt(i.a);
var x=document.createElement("button");x.className="x";x.type="button";x.textContent="Remove";
x.onclick=function(){items.splice(idx,1);render()};
r.appendChild(s);r.appendChild(x);list.appendChild(r)});
}
document.getElementById("add").onclick=function(){
var n=document.getElementById("name").value.trim();
var a=parseFloat(document.getElementById("amt").value);
if(!n||!(a>0))return;
items.unshift({n:n,a:a,c:document.getElementById("cat").value});
document.getElementById("name").value="";document.getElementById("amt").value="";
render()};
document.getElementById("budget").oninput=render;
render();
</script>
</body>
</html>
```
